<h1>User administration</h1><?php if($flash):?><div class="alert success"><?=e($flash)?></div><?php endif?><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif?><div class="grid two"><section class="panel"><h2>Create user</h2><form method="post" action="<?=e(url('/users'))?>"><?=csrf_field()?><label>Full name<input name="full_name" required></label><label>Email<input type="email" name="email" required></label><label>Temporary password (12+ characters)<input type="password" name="password" minlength="12" required></label><label>Role<select name="role_id" required><option value="">Choose role</option><?php foreach($roles as $role):?><option value="<?=e($role['id'])?>"><?=e($role['name'])?></option><?php endforeach?></select></label><button class="btn primary">Create user</button></form></section><section class="panel"><h2>Users</h2><div class="table-wrap"><table><tr><th>ID</th><th>Name</th><th>Email</th><th>Status</th><th>Last login</th></tr><?php foreach($users as $u):?><tr><td><?=e($u['id'])?></td><td><?=e($u['full_name'])?></td><td><?=e($u['email'])?></td><td><?=e($u['status'])?></td><td><?=e($u['last_login_at']??'—')?></td></tr><?php endforeach?></table></div></section></div>
